def address_without_unit(address: str) -> str | None:
    """'155 Clarke Road Unit 5 London, ON' -> '155 Clarke Road London, ON' (Nominatim often fails on unit numbers)."""
    cleaned = " ".join(UNIT_RE.sub(" ", address or "").split()).strip(" ,")
