import { useEffect } from "react";
import { CircleMarker, MapContainer, TileLayer, Tooltip, useMap } from "react-leaflet";
import { MapPinOff } from "lucide-react";
import { DEFAULT_MAP_CENTER } from "../config";
import { STATUS_STYLE, displayStatus } from "../lib/clinics";

function FitToPins({ points }) {
  const map = useMap();
  const key = points.map((p) => p.join(",")).join("|");
  useEffect(() => {
    if (points.length === 1) map.setView(points[0], 13);
    else if (points.length > 1) map.fitBounds(points, { padding: [40, 40], maxZoom: 14 });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [key]);
  return null;
}

/** Color-coded clinic pins. Clicking a pin calls onSelect(url) so the list can highlight + scroll to that card. */
export default function ClinicMap({ clinics, selectedUrl, onSelect }) {
  const located = clinics.filter((c) => typeof c.lat === "number" && typeof c.lng === "number");
  const missing = clinics.length - located.length;

  return (
    <div className="card relative h-full min-h-[320px] overflow-hidden p-0">
      <MapContainer center={DEFAULT_MAP_CENTER} zoom={12} scrollWheelZoom className="h-full min-h-[320px]">
        <TileLayer
          attribution='&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors'
          url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"
        />
        <FitToPins points={located.map((c) => [c.lat, c.lng])} />
        {located.map((c) => {
          const style = STATUS_STYLE[displayStatus(c)] || STATUS_STYLE.unknown;
          const selected = c.url === selectedUrl;
          return (
            <CircleMarker
              key={c.url}
              center={[c.lat, c.lng]}
              radius={selected ? 13 : 9}
              pathOptions={{ color: "#ffffff", weight: selected ? 3 : 2, fillColor: style.pin, fillOpacity: 0.95 }}
              eventHandlers={{ click: () => onSelect(c.url) }}
            >
              <Tooltip direction="top" offset={[0, -8]}>
                <div className="text-xs">
                  <div className="font-semibold">{c.name}</div>
                  <div>{style.label}{c.distance_km != null ? ` · ${c.distance_km} km` : ""}</div>
                </div>
              </Tooltip>
            </CircleMarker>
          );
        })}
      </MapContainer>

      <div className="pointer-events-none absolute bottom-3 left-3 z-[500] flex flex-wrap gap-2 rounded-lg bg-white/90 px-2 py-1 text-xs shadow-sm">
        {["accepting", "waitlist", "closed"].map((k) => (
          <span key={k} className="flex items-center gap-1 text-slate-600">
            <span className="h-2.5 w-2.5 rounded-full" style={{ background: STATUS_STYLE[k].pin }} />
            {STATUS_STYLE[k].label}
          </span>
        ))}
      </div>
      {missing > 0 && (
        <div className="pointer-events-none absolute right-3 top-3 z-[500] flex items-center gap-1 rounded-lg bg-white/90 px-2 py-1 text-xs text-slate-500 shadow-sm">
          <MapPinOff className="h-3.5 w-3.5" /> {missing} without a map location
        </div>
      )}
    </div>
  );
}

import { useState } from "react";
import { Check, Clock, Copy, Phone } from "lucide-react";

/** For clinics without an online waitlist: phone, hours and a read-aloud script (in the chosen language). */
export default function CallScript({ clinic }) {
  const [copied, setCopied] = useState(false);
  const copy = async () => {
    try {
      await navigator.clipboard.writeText(clinic.call_script || "");
      setCopied(true);
      setTimeout(() => setCopied(false), 1500);
    } catch {
      /* clipboard blocked: nothing to do */
    }
  };

  return (
    <div className="mt-3 space-y-2 rounded-lg border border-slate-200 bg-slate-50 p-3 text-sm">
      <div className="flex flex-wrap items-center gap-3">
        {clinic.phone_number ? (
          <a href={`tel:${clinic.phone_number}`} className="btn-primary py-1.5">
            <Phone className="h-4 w-4" /> Call {clinic.phone_number}
          </a>
        ) : (
          <span className="text-slate-500">No phone number listed on the clinic's site.</span>
        )}
        {clinic.call_hours && (
          <span className="flex items-center gap-1 text-slate-600"><Clock className="h-4 w-4" /> {clinic.call_hours}</span>
        )}
      </div>
      {clinic.call_script ? (
        <div className="relative rounded-md bg-white p-3 ring-1 ring-slate-200">
          <button onClick={copy} className="btn-ghost absolute right-1 top-1 px-2 py-1 text-xs" aria-label="Copy script">
            {copied ? <Check className="h-3.5 w-3.5" /> : <Copy className="h-3.5 w-3.5" />}
          </button>
          <p className="whitespace-pre-line pr-8 text-slate-700">{clinic.call_script}</p>
        </div>
      ) : (
        <p className="text-slate-500">No call script for this clinic.</p>
      )}
    </div>
  );
}

import { useState } from "react";
import { BadgeCheck, ExternalLink, Loader2, SearchCheck, ShieldAlert } from "lucide-react";
import { api } from "../api";

/** Small drawer: look a doctor up on the official CPSO register (POST /api/verify-doctor). */
export default function VerifyDoctor({ city }) {
  const [name, setName] = useState("");
  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState(null);
  const [error, setError] = useState(null);

  const verify = async (e) => {
    e.preventDefault();
    if (name.trim().length < 2) return;
    setLoading(true);
    setResult(null);
    setError(null);
    try {
      setResult(await api.verifyDoctor(name.trim(), (city || "London").split(",")[0].trim()));
    } catch (err) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="mt-3 rounded-lg border border-slate-200 bg-slate-50 p-3 text-sm">
      <form onSubmit={verify} className="flex gap-2">
        <input
          className="input"
          value={name}
          onChange={(e) => setName(e.target.value)}
          placeholder="Doctor's name, e.g. Jane Smith"
          minLength={2}
          maxLength={100}
          aria-label="Doctor's name"
        />
        <button className="btn-secondary shrink-0" disabled={loading || name.trim().length < 2}>
          {loading ? <Loader2 className="h-4 w-4 animate-spin" /> : <SearchCheck className="h-4 w-4" />} Verify
        </button>
      </form>
      {loading && <p className="mt-2 text-xs text-slate-500">Checking the CPSO register. This can take a minute or two.</p>}
      {error && <p className="mt-2 text-rose-700">{error}</p>}
      {result && (
        <div className="mt-3 space-y-1.5">
          {result.verified ? (
            <span className="badge bg-emerald-50 text-emerald-700 ring-emerald-600/20"><BadgeCheck className="h-3.5 w-3.5" /> CPSO verified</span>
          ) : (
            <span className="badge bg-amber-50 text-amber-700 ring-amber-600/20">
              <ShieldAlert className="h-3.5 w-3.5" />
              {result.lookup_status === "found" ? "Not active" : result.lookup_status === "not_found" ? "Not found" : "Couldn't verify"}
            </span>
          )}
          <dl className="grid grid-cols-[auto,1fr] gap-x-3 gap-y-1 text-xs">
            {result.cpso_number && (<><dt className="text-slate-500">CPSO #</dt><dd className="font-medium text-slate-800">{result.cpso_number}</dd></>)}
            {result.registration_status && (<><dt className="text-slate-500">Status</dt><dd className="text-slate-800">{result.registration_status}</dd></>)}
            {result.specialty && (<><dt className="text-slate-500">Specialty</dt><dd className="text-slate-800">{result.specialty}</dd></>)}
            {result.languages?.length > 0 && (<><dt className="text-slate-500">Languages</dt><dd className="text-slate-800">{result.languages.join(", ")}</dd></>)}
          </dl>
          {result.notes && <p className="text-xs text-slate-600">{result.notes}</p>}
          {result.profile_url && (
            <a href={result.profile_url} target="_blank" rel="noreferrer" className="inline-flex items-center gap-1 text-xs font-medium text-emerald-700 hover:underline">
              Official CPSO profile <ExternalLink className="h-3 w-3" />
            </a>
          )}
        </div>
      )}
    </div>
  );
}

import { useEffect, useState } from "react";
import { AlertTriangle, CheckCircle2, ExternalLink, Hand, Loader2, X } from "lucide-react";
import { api } from "../api";

/**
 * Auto-fill a clinic's waitlist form (POST /api/apply). The backend's agent fills the fields and STOPS before
 * Submit, so the patient always reviews and submits on the clinic's own page.
 */
export default function ApplyModal({ clinic, defaults, onClose }) {
  const [form, setForm] = useState({ name: "", email: defaults.email || "", phone: "", postal_code: defaults.postalCode || "" });
  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState(null);
  const [error, setError] = useState(null);

  useEffect(() => {
    const onKey = (e) => e.key === "Escape" && !loading && onClose();
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [loading, onClose]);

  const set = (k) => (e) => setForm({ ...form, [k]: e.target.value });

  const submit = async (e) => {
    e.preventDefault();
    setLoading(true);
    setError(null);
    setResult(null);
    try {
      setResult(await api.apply(clinic.waitlist_url, form));
    } catch (err) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="fixed inset-0 z-[2000] flex items-end justify-center bg-slate-900/40 p-4 sm:items-center" onClick={() => !loading && onClose()}>
      <div className="card max-h-[90vh] w-full max-w-lg overflow-y-auto p-5" role="dialog" aria-modal="true" aria-labelledby="apply-title" onClick={(e) => e.stopPropagation()}>
        <div className="flex items-start justify-between gap-3">
          <div>
            <h2 id="apply-title" className="text-base font-semibold text-slate-900">Auto-Fill Waitlist</h2>
            <p className="text-sm text-slate-500">{clinic.name}</p>
          </div>
          <button onClick={onClose} disabled={loading} className="btn-ghost px-2 py-1" aria-label="Close"><X className="h-4 w-4" /></button>
        </div>

        <div className="mt-3 flex items-start gap-2 rounded-lg bg-emerald-50 p-3 text-xs text-emerald-800">
          <Hand className="mt-0.5 h-4 w-4 shrink-0" />
          <span>CareScout fills in the form for you and <b>pauses before Submit</b>. You review and submit it yourself on the clinic's website.</span>
        </div>

        {!result && (
          <form onSubmit={submit} className="mt-4 grid grid-cols-1 gap-3 sm:grid-cols-2">
            <div className="sm:col-span-2">
              <label className="label" htmlFor="ap-name">Full name</label>
              <input id="ap-name" className="input" value={form.name} onChange={set("name")} required maxLength={120} autoComplete="name" />
            </div>
            <div className="sm:col-span-2">
              <label className="label" htmlFor="ap-email">Email</label>
              <input id="ap-email" type="email" className="input" value={form.email} onChange={set("email")} required maxLength={200} autoComplete="email" />
            </div>
            <div>
              <label className="label" htmlFor="ap-phone">Phone</label>
              <input id="ap-phone" type="tel" className="input" value={form.phone} onChange={set("phone")} required maxLength={40} autoComplete="tel" />
            </div>
            <div>
              <label className="label" htmlFor="ap-postal">Postal code</label>
              <input id="ap-postal" className="input" value={form.postal_code} onChange={set("postal_code")} required maxLength={12} autoComplete="postal-code" />
            </div>
            {error && <p className="text-sm text-rose-700 sm:col-span-2">{error}</p>}
            <div className="flex items-center justify-end gap-2 sm:col-span-2">
              {loading && <span className="text-xs text-slate-500">The agent is filling the form (up to ~2 min)...</span>}
              <button type="submit" className="btn-primary" disabled={loading}>
                {loading && <Loader2 className="h-4 w-4 animate-spin" />} Fill the form
              </button>
            </div>
          </form>
        )}

        {result && <ApplyResult result={result} clinic={clinic} onRetry={() => setResult(null)} />}
      </div>
    </div>
  );
}

function ApplyResult({ result, clinic, onRetry }) {
  const link = (
    <a href={clinic.waitlist_url} target="_blank" rel="noreferrer" className="btn-secondary">
      Open the clinic's form <ExternalLink className="h-4 w-4" />
    </a>
  );
  if (result.status === "ready_for_review") {
    const fields = Object.entries(result.filled_fields || {});
    return (
      <div className="mt-4 space-y-3">
        <div className="flex items-start gap-2 rounded-lg border border-emerald-200 bg-emerald-50 p-3 text-sm text-emerald-800">
          <CheckCircle2 className="mt-0.5 h-4 w-4 shrink-0" />
          <div>
            <div className="font-semibold">Ready for your review. Not submitted.</div>
            <div className="text-xs">The agent paused before the final Submit button. Open the form, check every field, and submit it yourself.</div>
          </div>
        </div>
        {fields.length > 0 && (
          <table className="w-full text-sm">
            <tbody>
              {fields.map(([k, v]) => (
                <tr key={k} className="border-b border-slate-100 last:border-0">
                  <td className="py-1.5 pr-3 text-slate-500">{k}</td>
                  <td className="py-1.5 font-medium text-slate-800">{String(v)}</td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
        {result.summary && <p className="text-xs text-slate-600">{result.summary}</p>}
        {result.screenshot_url && <img src={result.screenshot_url} alt="Filled form preview" className="w-full rounded-lg ring-1 ring-slate-200" />}
        <div className="flex justify-end">{link}</div>
      </div>
    );
  }
  const isError = result.status === "error";
  return (
    <div className="mt-4 space-y-3">
      <div className={`flex items-start gap-2 rounded-lg border p-3 text-sm ${isError ? "border-rose-200 bg-rose-50 text-rose-800" : "border-amber-200 bg-amber-50 text-amber-800"}`}>
        <AlertTriangle className="mt-0.5 h-4 w-4 shrink-0" />
        <div>
          <div className="font-semibold">{isError ? "Something went wrong" : "Please complete this one yourself"}</div>
          <div className="text-xs">{result.summary}</div>
        </div>
      </div>
      <div className="flex justify-end gap-2">
        <button onClick={onRetry} className="btn-ghost">Try again</button>
        {link}
      </div>
    </div>
  );
}

import { forwardRef, useState } from "react";
import { BellPlus, Check, ExternalLink, FileSignature, Loader2, MapPin, Phone, Quote, ShieldCheck } from "lucide-react";
import { api } from "../api";
import { displayStatus, isFailedScan } from "../lib/clinics";
import StatusBadge from "./StatusBadge";
import CallScript from "./CallScript";
import VerifyDoctor from "./VerifyDoctor";

function ScoreRing({ score }) {
  if (score == null) return null;
  const color = score >= 70 ? "text-emerald-600" : score >= 40 ? "text-amber-500" : "text-rose-500";
  const r = 18;
  const c = 2 * Math.PI * r;
  return (
    <div className="relative h-12 w-12 shrink-0" title={`Match score ${score}/100`}>
      <svg viewBox="0 0 44 44" className="h-12 w-12 -rotate-90">
        <circle cx="22" cy="22" r={r} fill="none" stroke="currentColor" strokeWidth="4" className="text-slate-100" />
        <circle cx="22" cy="22" r={r} fill="none" stroke="currentColor" strokeWidth="4" strokeLinecap="round"
          strokeDasharray={c} strokeDashoffset={c * (1 - score / 100)} className={color} />
      </svg>
      <span className="absolute inset-0 flex items-center justify-center text-sm font-semibold text-slate-800">{score}</span>
    </div>
  );
}

/** One clinic: scan + ranking data, and its actions (apply / call / verify doctor / watch). */
const ClinicCard = forwardRef(function ClinicCard({ clinic, selected, onSelect, onApply, email, city, onWatched }, ref) {
  const [panel, setPanel] = useState(null); // "call" | "verify" | null
  const [watchEmail, setWatchEmail] = useState("");
  const [watchState, setWatchState] = useState({ loading: false, done: false, error: null, askEmail: false });
  const failed = isFailedScan(clinic);
  const status = displayStatus(clinic);
  const host = String(clinic.url).replace(/^https?:\/\/(www\.)?/, "").split("/")[0];

  const toggle = (p) => setPanel((cur) => (cur === p ? null : p));

  const watch = async () => {
    const userEmail = (email || watchEmail).trim();
    if (!userEmail.includes("@")) {
      setWatchState((s) => ({ ...s, askEmail: true, error: userEmail ? "Enter a valid email." : null }));
      return;
    }
    setWatchState({ loading: true, done: false, error: null, askEmail: false });
    try {
      await api.addWatch(clinic, userEmail);
      setWatchState({ loading: false, done: true, error: null, askEmail: false });
      onWatched?.(userEmail);
    } catch (e) {
      setWatchState({ loading: false, done: false, error: e.message, askEmail: true });
    }
  };

  return (
    <article
      ref={ref}
      onClick={() => onSelect(clinic.url)}
      className={`card scroll-mt-24 p-4 transition ${selected ? "ring-2 ring-emerald-500" : "hover:border-slate-300"}`}
    >
      <div className="flex items-start gap-3">
        <ScoreRing score={clinic.score} />
        <div className="min-w-0 flex-1">
          <div className="flex flex-wrap items-center gap-2">
            <h3 className="truncate font-semibold text-slate-900">{failed ? host : clinic.name}</h3>
            <StatusBadge clinic={clinic} />
          </div>
          <div className="mt-1 flex flex-wrap items-center gap-x-3 gap-y-1 text-xs text-slate-500">
            {clinic.distance_km != null && <span className="flex items-center gap-1"><MapPin className="h-3.5 w-3.5" />{clinic.distance_km} km away</span>}
            {clinic.address && <span className="truncate">{clinic.address}</span>}
            <a href={clinic.url} target="_blank" rel="noreferrer" onClick={(e) => e.stopPropagation()} className="flex items-center gap-1 hover:text-emerald-700">
              {host} <ExternalLink className="h-3 w-3" />
            </a>
          </div>
          {clinic.coverage_tags?.length > 0 && (
            <div className="mt-2 flex flex-wrap gap-1">
              {clinic.coverage_tags.map((t) => <span key={t} className="badge bg-sky-50 text-sky-700 ring-sky-600/20">{t}</span>)}
            </div>
          )}
        </div>
      </div>

      {failed ? (
        <p className="mt-3 text-sm text-slate-600">We couldn't check this clinic's website automatically. Visit the site or call them directly.</p>
      ) : (
        <div className="mt-3 space-y-2 text-sm">
          {clinic.reason && <p className="text-slate-700">{clinic.reason}</p>}
          {clinic.next_step && <p className="font-medium text-emerald-800"><span className="text-slate-500">Next step: </span>{clinic.next_step}</p>}
          {clinic.requirements?.length > 0 && (
            <ul className="list-inside list-disc text-xs text-slate-600">
              {clinic.requirements.map((r) => <li key={r}>{r}</li>)}
            </ul>
          )}
          {clinic.evidence_quote && (
            <blockquote className="flex gap-2 rounded-lg bg-slate-50 p-2 text-xs italic text-slate-600">
              <Quote className="h-3.5 w-3.5 shrink-0 text-slate-400" />
              <span>{clinic.evidence_quote}</span>
            </blockquote>
          )}
          {!clinic.ranked && <p className="text-xs text-slate-400">Ranking pending...</p>}
        </div>
      )}

      <div className="mt-3 flex flex-wrap gap-2" onClick={(e) => e.stopPropagation()}>
        {clinic.waitlist_url ? (
          <button onClick={() => onApply(clinic)} className="btn-primary py-1.5">
            <FileSignature className="h-4 w-4" /> Auto-Fill Waitlist
          </button>
        ) : (
          !failed && (
            <button onClick={() => toggle("call")} className={`btn-secondary py-1.5 ${panel === "call" ? "bg-slate-100" : ""}`}>
              <Phone className="h-4 w-4" /> {panel === "call" ? "Hide Call Script" : "View Call Script"}
            </button>
          )
        )}
        <button onClick={() => toggle("verify")} className={`btn-secondary py-1.5 ${panel === "verify" ? "bg-slate-100" : ""}`}>
          <ShieldCheck className="h-4 w-4" /> Verify Doctor (CPSO)
        </button>
        {status === "closed" && (
          watchState.done ? (
            <span className="btn py-1.5 text-emerald-700"><Check className="h-4 w-4" /> Watching</span>
          ) : (
            <button onClick={watch} disabled={watchState.loading} className="btn-secondary py-1.5">
              {watchState.loading ? <Loader2 className="h-4 w-4 animate-spin" /> : <BellPlus className="h-4 w-4" />} Watch Clinic
            </button>
          )
        )}
      </div>

      {watchState.askEmail && !email && (
        <div className="mt-2 flex gap-2" onClick={(e) => e.stopPropagation()}>
          <input
            type="email"
            className="input py-1.5"
            placeholder="Email for opening alerts"
            value={watchEmail}
            onChange={(e) => setWatchEmail(e.target.value)}
            onKeyDown={(e) => e.key === "Enter" && watch()}
          />
          <button onClick={watch} className="btn-primary py-1.5">Watch</button>
        </div>
      )}
      {watchState.error && <p className="mt-1 text-xs text-rose-700">{watchState.error}</p>}

      <div onClick={(e) => e.stopPropagation()}>
        {panel === "call" && <CallScript clinic={clinic} />}
        {panel === "verify" && <VerifyDoctor city={city} />}
      </div>
    </article>
  );
});

