import { useCallback, useEffect, useState } from "react";
import { Bell, ExternalLink, Eye, Loader2, RefreshCw, Sparkles, Trash2 } from "lucide-react";
import { api } from "../api";
import StatusBadge from "./StatusBadge";

function ago(iso) {
  if (!iso) return "not checked yet";
  const mins = Math.round((Date.now() - new Date(iso).getTime()) / 60000);
  if (mins < 1) return "checked just now";
  if (mins < 60) return `checked ${mins} min ago`;
  const h = Math.round(mins / 60);
  return h < 24 ? `checked ${h} h ago` : `checked ${Math.round(h / 24)} d ago`;
}

/** Monitored clinics (GET /api/watch), "Check All Now", alert history, and the demo "Simulate Opening". */
export default function WatchdogView({ email, onEmail, onAlert, onChanged }) {
  const [watches, setWatches] = useState([]);
  const [alerts, setAlerts] = useState([]);
  const [loading, setLoading] = useState(true);
  const [checking, setChecking] = useState(false);
  const [simulating, setSimulating] = useState(false);
  const [message, setMessage] = useState(null);
  const [error, setError] = useState(null);
  const userEmail = email.includes("@") ? email.trim() : undefined;

  const load = useCallback(async () => {
    setError(null);
    try {
      const [w, a] = await Promise.all([api.listWatches(userEmail), api.watchAlerts(userEmail, 10)]);
      setWatches(w.watched_clinics);
      setAlerts(a.alerts);
      onChanged?.(w.watched_clinics.length);
    } catch (e) {
      setError(e.message);
    } finally {
      setLoading(false);
    }
  }, [userEmail, onChanged]);

  useEffect(() => {
    load();
  }, [load]);

  const checkAll = async () => {
    setChecking(true);
    setMessage(null);
    setError(null);
    try {
      const r = await api.checkWatches(userEmail);
      setMessage(`Checked ${r.checked} clinic${r.checked === 1 ? "" : "s"}${r.failed ? ` (${r.failed} couldn't be checked)` : ""}. ${r.alerts.length ? `${r.alerts.length} changed!` : "No changes yet."}`);
      if (r.alerts[0]) onAlert(r.alerts[0]);
      await load();
    } catch (e) {
      setError(e.message);
    } finally {
      setChecking(false);
    }
  };

  const simulate = async (watchId) => {
    setSimulating(true);
    setError(null);
    try {
      const r = await api.simulateOpening(watchId);
      onAlert(r.alert);
      await load();
    } catch (e) {
      setError(e.message);
    } finally {
      setSimulating(false);
    }
  };

  const remove = async (w) => {
    if (!userEmail) {
      setError("Enter your email above to manage your watches.");
      return;
    }
    try {
      await api.deleteWatch(w.id, userEmail);
      await load();
    } catch (e) {
      setError(e.message);
    }
  };

  return (
    <div className="space-y-4">
      <section className="card p-4">
        <div className="flex flex-wrap items-end justify-between gap-3">
          <div>
            <h2 className="flex items-center gap-2 text-base font-semibold text-slate-900"><Eye className="h-5 w-5 text-emerald-600" /> Clinic Watchdog</h2>
            <p className="text-sm text-slate-500">CareScout re-checks full clinics and alerts you the moment one opens.</p>
          </div>
          <div className="flex flex-wrap items-end gap-2">
            <div>
              <label className="label" htmlFor="wd-email">Your email</label>
              <input id="wd-email" type="email" className="input w-64" value={email} onChange={(e) => onEmail(e.target.value)} placeholder="you@example.com" />
            </div>
            <button onClick={checkAll} disabled={checking || watches.length === 0} className="btn-primary">
              {checking ? <Loader2 className="h-4 w-4 animate-spin" /> : <RefreshCw className="h-4 w-4" />} Check All Now
            </button>
          </div>
        </div>
        {!userEmail && <p className="mt-2 text-xs text-amber-700">Showing everyone's watches with emails hidden. Enter your email to see only yours.</p>}
        {checking && <p className="mt-2 text-xs text-slate-500">Agents are re-checking each clinic's website. This takes a few minutes.</p>}
        {message && <p className="mt-2 text-sm text-emerald-700">{message}</p>}
        {error && <p className="mt-2 text-sm text-rose-700">{error}</p>}
      </section>

      <section className="card divide-y divide-slate-100">
        {loading ? (
          <div className="flex items-center gap-2 p-4 text-sm text-slate-500"><Loader2 className="h-4 w-4 animate-spin" /> Loading watched clinics...</div>
        ) : watches.length === 0 ? (
          <div className="p-6 text-center text-sm text-slate-500">
            No watched clinics yet. Use <b>Watch Clinic</b> on any full clinic, or add your email before launching a search to auto-watch them.
          </div>
        ) : (
          watches.map((w) => (
            <div key={w.id} className="flex flex-wrap items-center gap-3 p-4">
              <div className="min-w-0 flex-1">
                <div className="flex flex-wrap items-center gap-2">
                  <span className="font-medium text-slate-900">{w.clinic_name}</span>
                  <StatusBadge status={w.last_status} />
                </div>
                <div className="mt-0.5 flex flex-wrap gap-x-3 text-xs text-slate-500">
                  <a href={w.url} target="_blank" rel="noreferrer" className="flex items-center gap-1 hover:text-emerald-700">
                    {w.url.replace(/^https?:\/\/(www\.)?/, "").split("/")[0]} <ExternalLink className="h-3 w-3" />
                  </a>
                  <span>{ago(w.last_checked)}</span>
                  {!userEmail && <span>{w.user_email}</span>}
                </div>
              </div>
              <button onClick={() => simulate(w.id)} disabled={simulating} className="btn-ghost py-1 text-xs text-slate-400 hover:text-emerald-700" title="Demo only">
                <Sparkles className="h-3.5 w-3.5" /> Simulate
              </button>
              {userEmail && (
                <button onClick={() => remove(w)} className="btn-ghost px-2 py-1 text-slate-400 hover:text-rose-600" aria-label={`Stop watching ${w.clinic_name}`}>
                  <Trash2 className="h-4 w-4" />
                </button>
              )}
            </div>
          ))
        )}
      </section>

      {alerts.length > 0 && (
        <section className="card p-4">
          <h3 className="flex items-center gap-2 text-sm font-semibold text-slate-900"><Bell className="h-4 w-4" /> Recent alerts</h3>
          <ul className="mt-2 space-y-2 text-sm">
            {alerts.map((a) => (
              <li key={a.alert_id} className="flex items-start gap-2">
                <span className="mt-1.5 h-2 w-2 shrink-0 rounded-full bg-emerald-500" />
                <span className="text-slate-700">{a.message}</span>
                {a.simulated && <span className="badge bg-slate-100 text-slate-500 ring-slate-200">demo</span>}
                <span className="ml-auto shrink-0 text-xs text-slate-400">{new Date(a.created_at).toLocaleString()}</span>
              </li>
            ))}
          </ul>
        </section>
      )}

      <div className="flex justify-end">
        <button onClick={() => simulate(undefined)} disabled={simulating || watches.length === 0} className="btn-ghost text-xs text-slate-400 hover:text-emerald-700" title="For live demos: pretends the newest watched clinic just opened">
          {simulating ? <Loader2 className="h-3.5 w-3.5 animate-spin" /> : <Sparkles className="h-3.5 w-3.5" />} Simulate Opening (Demo)
        </button>
      </div>
    </div>
  );
}

