function EmptyState() {
  const steps = [
    { icon: MapPinned, title: "Scout", text: "Finds clinic websites in your city." },
    { icon: Bot, title: "Browser Swarm", text: "AI agents read each site to see who's accepting patients." },
    { icon: Sparkles, title: "Triage", text: "Gemini ranks them for you, in your language, with next steps." },
  ];
  return (
