export default function App() {
  const [tab, setTab] = useState("find");
  const [search, setSearch] = useState(DEFAULT_SEARCH);
  const { state, start, stop, reset } = useMission();
  const [selectedUrl, setSelectedUrl] = useState(null);
  const [applyFor, setApplyFor] = useState(null);
  const [alert, setAlert] = useState(null);
  const [watchCount, setWatchCount] = useState(0);
  const cardRefs = useRef({});

  const clinics = useMemo(() => mergeClinics(state.scanned, state.urls, state.ranked), [state.scanned, state.urls, state.ranked]);
  const email = search.email.trim();

  const refreshWatchCount = useCallback(async () => {
    try {
      const r = await api.listWatches(email.includes("@") ? email : undefined);
      setWatchCount(r.watched_clinics.length);
    } catch {
      /* backend offline: keep the old count */
    }
  }, [email]);

  useEffect(() => {
    refreshWatchCount();
  }, [refreshWatchCount]);

  useEffect(() => {
    if (state.watched.length) refreshWatchCount(); // mission auto-enrolled closed clinics
  }, [state.watched, refreshWatchCount]);

  const launch = () => {
    setSelectedUrl(null);
    start({
      city: search.city.trim() || "London, ON",
      user_postal_code: search.postalCode.trim() || null,
      preferences: [],
      language: search.language,
      coverage_type: search.coverage,
      user_email: email || null,
      auto_watch_closed: true,
      use_cache: search.useCache,
    });
  };

  const selectClinic = useCallback((url) => {
    setSelectedUrl(url);
    cardRefs.current[url]?.scrollIntoView({ behavior: "smooth", block: "nearest" });
  }, []);

  const onWatchEmail = useCallback((value) => setSearch((s) => ({ ...s, email: value })), []);
  const onWatchChanged = useCallback((n) => setWatchCount(n), []);

  return (
    <div className="min-h-screen">
      <Header tab={tab} onTab={setTab} watchCount={watchCount} />
      <AlertBanner alert={alert} onClose={() => setAlert(null)} />

      <main className="mx-auto max-w-7xl space-y-4 px-4 py-5">
        {tab === "find" ? (
          <>
            <MissionForm values={search} onChange={setSearch} onLaunch={launch} onStop={stop} running={state.running} />
            <AgentFeed state={state} onStop={stop} onReset={reset} />

            {clinics.length > 0 ? (
              <div className="grid gap-4 lg:grid-cols-5">
                <div className="lg:col-span-2">
                  <div className="h-[360px] lg:sticky lg:top-24 lg:h-[calc(100vh-8rem)]">
                    <ClinicMap clinics={clinics} selectedUrl={selectedUrl} onSelect={selectClinic} />
                  </div>
                </div>
                <div className="space-y-3 lg:col-span-3">
                  {clinics.map((c) => (
                    <ClinicCard
                      key={c.url}
                      id={clinicDomId(c.url)}
                      ref={(el) => (cardRefs.current[c.url] = el)}
                      clinic={c}
                      selected={c.url === selectedUrl}
                      onSelect={setSelectedUrl}
                      onApply={setApplyFor}
                      email={email}
                      city={search.city}
                      onWatched={refreshWatchCount}
                    />
                  ))}
                </div>
              </div>
            ) : (
              !state.running && state.log.length === 0 && <EmptyState />
            )}
          </>
        ) : (
          <WatchdogView email={search.email} onEmail={onWatchEmail} onAlert={setAlert} onChanged={onWatchChanged} />
        )}
      </main>

      {applyFor && <ApplyModal clinic={applyFor} defaults={search} onClose={() => setApplyFor(null)} />}
    </div>
  );
}

