@tailwind base;
@tailwind components;
@tailwind utilities;

@layer base {
  html {
    -webkit-font-smoothing: antialiased;
    scroll-behavior: smooth;
  }
  body {
    @apply bg-paper font-sans text-[15px] leading-relaxed text-slate-700;
  }
  h1, h2, h3 {
    @apply font-display text-ink;
    font-optical-sizing: auto;
  }
  :focus-visible {
    @apply outline-none ring-2 ring-pine-500 ring-offset-2 ring-offset-paper;
  }
}

@layer components {
  /* Surfaces: large panels get the big radius, controls a smaller one. Borders over shadows. */
  .card {
    @apply rounded-2xl border border-slate-200/80 bg-white;
  }
  .btn {
    @apply inline-flex items-center justify-center gap-1.5 rounded-[10px] px-3.5 py-2 text-sm font-semibold transition
      disabled:cursor-not-allowed disabled:opacity-50;
  }
  .btn-primary {
    @apply btn bg-pine-600 text-white hover:bg-pine-700 active:bg-pine-800;
  }
  .btn-secondary {
    @apply btn border border-slate-200 bg-white text-slate-700 hover:border-slate-300 hover:bg-slate-50;
  }
  .btn-ghost {
    @apply btn font-medium text-slate-600 hover:bg-slate-100;
  }
  .btn-lg {
    @apply rounded-xl px-5 py-3 text-base;
  }
  .input {
    @apply w-full rounded-[10px] border border-slate-200 bg-white px-3 py-2 text-sm text-ink placeholder:text-slate-400
      focus:border-pine-500 focus:outline-none focus:ring-2 focus:ring-pine-500/20;
  }
  .label {
    @apply mb-1 block text-xs font-medium text-slate-500;
  }
  .badge {
    @apply inline-flex items-center gap-1 rounded-full px-2 py-0.5 text-xs font-medium ring-1 ring-inset;
  }
  .container-page {
    @apply mx-auto w-full max-w-6xl px-4 sm:px-6;
  }
}

