"""Clinic database: every clinic CareScout knows about, its details and its latest availability (SQLite).

Clinic details (name, address, map location) rarely change; availability does. Searches read from here instantly and
only re-check clinics that are out of date (see refresh.py). No FastAPI code here.
"""
import contextlib
import json
import os
import sqlite3
from datetime import datetime, timedelta, timezone
from pathlib import Path
from urllib.parse import urlparse

DB_PATH = Path(os.getenv("DATA_DIR") or Path(__file__).resolve().parents[1]) / "clinics.db"  # same file as watchdog.py
STATUSES = ("accepting", "waitlist", "closed")
STATUS_ORDER = {"accepting": 0, "waitlist": 1, "closed": 2}
FIELDS = ("name", "status", "evidence_quote", "waitlist_url", "raw_notes", "address", "lat", "lng")


def now_iso() -> str:
    return datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")


def parse_iso(value: str | None) -> datetime | None:
    try:
        return datetime.strptime(value, "%Y-%m-%dT%H:%M:%SZ").replace(tzinfo=timezone.utc) if value else None
    except ValueError:
        return None


def city_key(city: str | None) -> str:
    """'London, ON' -> 'london' (searches match on the city name only)."""
    return (city or "").split(",")[0].strip().lower()


def url_key(url: str) -> str:
    """One row per page: https://www.X.ca/page/ and http://x.ca/page are the same clinic page."""
    p = urlparse((url or "").strip())
    host = (p.hostname or "").lower().removeprefix("www.")
    path = p.path.rstrip("/")
    return f"{host}{path}" + (f"?{p.query}" if p.query else "")


def connect() -> sqlite3.Connection:
    DB_PATH.parent.mkdir(parents=True, exist_ok=True)
    conn = sqlite3.connect(DB_PATH, timeout=10)
    conn.row_factory = sqlite3.Row
    conn.execute(
        "CREATE TABLE IF NOT EXISTS clinics ("
        "url_key TEXT PRIMARY KEY, url TEXT NOT NULL, name TEXT, city TEXT, city_key TEXT, "
        "status TEXT, evidence_quote TEXT, waitlist_url TEXT, raw_notes TEXT, address TEXT, lat REAL, lng REAL, "
        "content_hash TEXT, checked_via TEXT, last_checked TEXT, last_changed TEXT, "
        "last_error TEXT, fail_count INTEGER DEFAULT 0, source TEXT, created_at TEXT)"
    )
    conn.execute("CREATE INDEX IF NOT EXISTS clinics_city ON clinics(city_key)")
    conn.execute("CREATE TABLE IF NOT EXISTS meta (key TEXT PRIMARY KEY, value TEXT)")
    return conn


# ---------- reads ----------

def get(url: str) -> dict | None:
    with contextlib.closing(connect()) as conn:
        row = conn.execute("SELECT * FROM clinics WHERE url_key = ?", (url_key(url),)).fetchone()
    return dict(row) if row else None


def count() -> int:
    with contextlib.closing(connect()) as conn:
        return conn.execute("SELECT COUNT(*) FROM clinics").fetchone()[0]


def is_fresh(row: dict | None, hours: float) -> bool:
    checked = parse_iso((row or {}).get("last_checked"))
    return bool(row and row.get("status") and checked and datetime.now(timezone.utc) - checked < timedelta(hours=hours))


def to_clinic(row: dict) -> dict:
    """A database row in the API's clinic shape (plus last_checked / checked_via)."""
    return {
        "name": row.get("name") or row["url"],
        "url": row["url"],
        "status": row.get("status") or "closed",
        "evidence_quote": row.get("evidence_quote") or "",
        "waitlist_url": row.get("waitlist_url") or None,
        "raw_notes": row.get("raw_notes") or "",
        "address": row.get("address") or None,
        "lat": row.get("lat"),
        "lng": row.get("lng"),
        "distance_km": None,
        "last_checked": row.get("last_checked"),
        "checked_via": row.get("checked_via") or "saved",
    }


def nearby(city: str, user_loc: dict | None, limit: int, include_unchecked: bool = True) -> list[dict]:
    """Clinics in this city, closest first when the patient's location is known (else accepting first)."""
    from .geo import haversine_km  # local import: geo is only needed for distance sorting

    with contextlib.closing(connect()) as conn:
        rows = [dict(r) for r in conn.execute("SELECT * FROM clinics WHERE city_key = ?", (city_key(city),)).fetchall()]
    if not include_unchecked:
        rows = [r for r in rows if r.get("status")]

    def sort_key(r):
        if user_loc and r.get("lat") is not None and r.get("lng") is not None:
            dist = haversine_km(user_loc["lat"], user_loc["lng"], r["lat"], r["lng"])
        else:
            dist = float("inf")
        return (dist, STATUS_ORDER.get(r.get("status"), 3), (r.get("name") or r["url"]).lower())

    return sorted(rows, key=sort_key)[: max(0, limit)]


def stale(limit: int, hours: float) -> list[dict]:
    """Clinics that need a re-check: never checked first, then the longest ago."""
    cutoff = (datetime.now(timezone.utc) - timedelta(hours=hours)).strftime("%Y-%m-%dT%H:%M:%SZ")
    with contextlib.closing(connect()) as conn:
        rows = conn.execute(
            "SELECT * FROM clinics WHERE status IS NULL OR last_checked IS NULL OR last_checked < ? "
            "ORDER BY (last_checked IS NOT NULL), last_checked LIMIT ?",
            (cutoff, max(0, limit)),
        ).fetchall()
    return [dict(r) for r in rows]


def stats(hours: float) -> dict:
    with contextlib.closing(connect()) as conn:
        rows = [dict(r) for r in conn.execute("SELECT status, last_checked, city FROM clinics").fetchall()]
        last = conn.execute("SELECT value FROM meta WHERE key = 'last_refresh'").fetchone()
    checked = [r for r in rows if r["status"]]
    return {
        "total": len(rows),
        "checked": len(checked),
        "fresh": sum(is_fresh(r, hours) for r in rows),
        "by_status": {s: sum(r["status"] == s for r in rows) for s in STATUSES},
        "cities": sorted({(r["city"] or "").strip() for r in rows if r["city"]}),
        "last_refresh": last["value"] if last else None,
    }


# ---------- writes ----------

def add_url(url: str, city: str, name: str | None = None, source: str = "discovered") -> bool:
    """Add a clinic page we haven't seen before (unchecked). Returns True if it was new."""
    with contextlib.closing(connect()) as conn, conn:
        cur = conn.execute(
            "INSERT OR IGNORE INTO clinics (url_key, url, name, city, city_key, source, created_at) VALUES (?, ?, ?, ?, ?, ?, ?)",
            (url_key(url), url.strip(), name, city, city_key(city), source, now_iso()),
        )
    return cur.rowcount > 0


def save_check(url: str, city: str, clinic: dict, content_hash: str | None, checked_via: str) -> tuple[dict, str | None]:
    """Store a successful check. Returns (row, old_status). Keeps coordinates if the address didn't change."""
    add_url(url, city, clinic.get("name"))
    old = get(url) or {}
    stamp = now_iso()
    values = {f: clinic.get(f) for f in FIELDS}
    if values["lat"] is None and (values["address"] or None) == (old.get("address") or None):
        values["lat"], values["lng"] = old.get("lat"), old.get("lng")
    changed = old.get("status") != values["status"]
    with contextlib.closing(connect()) as conn, conn:
        conn.execute(
            "UPDATE clinics SET name=?, status=?, evidence_quote=?, waitlist_url=?, raw_notes=?, address=?, lat=?, lng=?, "
            "content_hash=?, checked_via=?, last_checked=?, last_changed=CASE WHEN ? THEN ? ELSE last_changed END, "
            "last_error=NULL, fail_count=0, city=COALESCE(city, ?), city_key=COALESCE(city_key, ?) WHERE url_key=?",
            (values["name"], values["status"], values["evidence_quote"], values["waitlist_url"], values["raw_notes"],
             values["address"], values["lat"], values["lng"], content_hash, checked_via, stamp, changed, stamp,
             city, city_key(city), url_key(url)),
        )
    return get(url), old.get("status")


def mark_unchanged(url: str) -> dict | None:
    """The page text is the same as last time: the stored result is still right, just re-stamp it."""
    with contextlib.closing(connect()) as conn, conn:
        conn.execute("UPDATE clinics SET last_checked=?, last_error=NULL, fail_count=0 WHERE url_key=?", (now_iso(), url_key(url)))
    return get(url)


def mark_failed(url: str, error: str) -> dict | None:
    """A check failed: keep the last good result (if any) and remember the error."""
    with contextlib.closing(connect()) as conn, conn:
        conn.execute("UPDATE clinics SET last_error=?, fail_count=COALESCE(fail_count, 0) + 1 WHERE url_key=?", (error[:300], url_key(url)))
    return get(url)


def set_location(url: str, lat: float | None, lng: float | None) -> None:
    if lat is None or lng is None:
        return
    with contextlib.closing(connect()) as conn, conn:
        conn.execute("UPDATE clinics SET lat=?, lng=? WHERE url_key=? AND lat IS NULL", (lat, lng, url_key(url)))


def set_meta(key: str, value: str) -> None:
    with contextlib.closing(connect()) as conn, conn:
        conn.execute("INSERT INTO meta (key, value) VALUES (?, ?) ON CONFLICT(key) DO UPDATE SET value = excluded.value", (key, value))


# ---------- seeding ----------

def seed_if_empty(seed_path: Path, cache_path: Path, default_urls: list[str]) -> int:
    """Fill an empty database from seed_clinics.json, the saved demo scan and the default London clinics.
    Returns how many clinics were added (0 if the database already had any)."""
    if count():
        return 0
    added = 0

    def load(path: Path) -> list[dict]:
        try:
            data = json.loads(path.read_text(encoding="utf-8"))
            return [c for c in data.get("clinics", []) if isinstance(c, dict) and c.get("url")]
        except Exception:
            return []

    def mtime_iso(path: Path) -> str | None:
        try:
            return datetime.fromtimestamp(path.stat().st_mtime, timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")
        except OSError:
            return None

    for path, default_checked in ((seed_path, None), (cache_path, mtime_iso(cache_path))):
        for c in load(path):
            if c.get("raw_notes", "").startswith(("scan failed", "scan error")):
                continue
            city = c.get("city") or "London, ON"
            if not add_url(c["url"], city, c.get("name"), source="seed"):
                continue
            added += 1
            if c.get("status") in STATUSES:
                with contextlib.closing(connect()) as conn, conn:
                    conn.execute(
                        "UPDATE clinics SET status=?, evidence_quote=?, waitlist_url=?, raw_notes=?, address=?, lat=?, lng=?, "
                        "checked_via=?, last_checked=? WHERE url_key=?",
                        (c["status"], c.get("evidence_quote") or "", c.get("waitlist_url"), c.get("raw_notes") or "",
                         c.get("address"), c.get("lat"), c.get("lng"), c.get("checked_via") or "saved",
                         c.get("last_checked") or default_checked, url_key(c["url"])),
                    )
    for url in default_urls:
        added += add_url(url, "London, ON", source="seed")
    return added


def export_rows() -> list[dict]:
    """Every checked clinic, for writing a new seed_clinics.json."""
    with contextlib.closing(connect()) as conn:
        rows = [dict(r) for r in conn.execute("SELECT * FROM clinics WHERE status IS NOT NULL ORDER BY city_key, name").fetchall()]
    keep = ("url", "name", "city", "status", "evidence_quote", "waitlist_url", "raw_notes", "address", "lat", "lng", "checked_via", "last_checked")
    return [{k: r.get(k) for k in keep} for r in rows]

"""Mission Control: clinic database -> re-check what's out of date -> Gemini rank -> watchdog, in one live stream:
POST /api/mission/stream."""
import asyncio
import time
from datetime import datetime, timezone

from fastapi import APIRouter, HTTPException, Request
from fastapi.responses import StreamingResponse

from . import config, common, models, cache, watchdog, scanning, discovery, ranking, clinic_db, refresh

router = APIRouter()


def ago(iso: str | None) -> str:
    """'2026-11-21T10:00:00Z' -> '3 h ago'."""
    checked = clinic_db.parse_iso(iso)
    if not checked:
        return "earlier"
    mins = int((datetime.now(timezone.utc) - checked).total_seconds() // 60)
    if mins < 1:
        return "just now"
    if mins < 60:
        return f"{mins} min ago"
    if mins < 48 * 60:
        return f"{mins // 60} h ago"
    return f"{mins // (24 * 60)} days ago"


@router.post("/api/mission/stream")
async def mission_stream(req: models.MissionRequest, request: Request):
    """Flagship: Scout (clinic database, web search only when it needs more) -> re-check out-of-date clinics
    (quick page read, browser agent as fallback) -> Gemini Triage (rank) -> Watchdog enroll.
    Streams SSE events for every stage and ALWAYS ends with a done event, even if a stage fails."""
    if req.user_email and "@" not in req.user_email:
        raise HTTPException(status_code=422, detail="user_email must be a valid email address.")
    city = req.city.strip() or "London, ON"
    limit = max(1, min(req.max_clinics, config.MAX_MISSION_CLINICS))
    refresh_mode = req.refresh if req.refresh in ("auto", "all", "none") else "auto"
    public = config.public_restricted(request)
    saved_only = req.use_cache or public or refresh_mode == "none"

    # Saved-only searches never go live. With nothing saved they fall back to the demo cache; a public visitor gets a 503.
    fallback = None
    if saved_only and not clinic_db.nearby(city, None, 1, include_unchecked=False):
        fallback = cache.load_cache()
        if not fallback:
            if public:
                raise HTTPException(status_code=503, detail="The demo results aren't available right now. Try again later.")
            print("[mission] nothing saved for this city and no demo cache; running live")
            saved_only = False
    if not saved_only:
        config.require_key("TINYFISH_API_KEY")  # fail with a JSON 500 before the stream starts
    custom_urls, _ = scanning.pick_urls(models.ScanRequest(clinic_urls=req.clinic_urls)) if req.clinic_urls else ([], False)
    started_at = time.monotonic()

    async def events():
        clinics: list[dict] = []
        ranked: list[dict] = []
        watched: list[dict] = []
        tasks: list[asyncio.Task] = []
        counts = {"from_database": 0, "rechecked": 0}
        user_task = asyncio.create_task(scanning.user_location(req.user_postal_code))
        try:
            # ---- Stage 1: Scout (database first, web search only for more) ----
            yield common.sse({"type": "stage", "stage": "discover", "message": f"Scout Agent looking for clinics in {city}..."})
            urls: list[str] = []
            try:
                if fallback:
                    urls = [c["url"] for c in fallback["clinics"]][:limit]
                    yield common.sse({"type": "stage", "stage": "discover", "message": "Demo mode: using saved clinic results."})
                elif custom_urls:
                    urls = custom_urls[:limit]
                    for u in urls:
                        clinic_db.add_url(u, city, source="manual")
                else:
                    try:
                        user_loc = await asyncio.wait_for(asyncio.shield(user_task), timeout=10)
                    except Exception:
                        user_loc = None
                    rows = clinic_db.nearby(city, user_loc, limit, include_unchecked=not saved_only)
                    if saved_only:
                        yield common.sse({"type": "stage", "stage": "discover",
                                          "message": f"Using saved results for {len(rows)} clinics from the CareScout database."})
                    elif len(rows) < limit:
                        yield common.sse({"type": "stage", "stage": "discover", "message":
                                          f"{len(rows)} clinics in the CareScout database; searching the web for more..."})
                        try:
                            want = min(20, limit - len(rows) + 3)
                            task = asyncio.create_task(asyncio.to_thread(discovery.discover, models.DiscoverRequest(city=city, max_results=want)))
                            async for ka in common.wait_with_keepalive(task):
                                yield ka
                            new = sum(clinic_db.add_url(u, city) for u in task.result()["clinic_urls"])
                            if new:
                                yield common.sse({"type": "stage", "stage": "discover", "message": f"Added {new} new clinic websites to the database."})
                        except Exception as e:
                            yield common.sse({"type": "error", "stage": "discover", "message": f"Web search failed: {getattr(e, 'detail', None) or e}"})
                        if city.lower().startswith("london"):
                            for u in config.DEFAULT_CLINIC_URLS:
                                clinic_db.add_url(u, city, source="seed")
                        rows = clinic_db.nearby(city, user_loc, limit, include_unchecked=True)
                    else:
                        yield common.sse({"type": "stage", "stage": "discover", "message": f"Found {len(rows)} clinics in the CareScout database."})
                    urls = [r["url"] for r in rows]
            except Exception as e:
                yield common.sse({"type": "error", "stage": "discover", "message": f"Clinic search failed: {getattr(e, 'detail', None) or e}"})
            yield common.sse({"type": "discovered", "urls": urls})

            # ---- Stage 2: re-check only what's out of date ----
            rows_by_url = {u: clinic_db.get(u) for u in urls}
            if fallback:
                fresh, stale = [], []
            elif saved_only:
                fresh, stale = [u for u in urls if (rows_by_url[u] or {}).get("status")], []
            else:
                fresh = [u for u in urls if refresh_mode == "auto" and clinic_db.is_fresh(rows_by_url[u], config.FRESH_HOURS)]
                stale = [u for u in urls if u not in fresh]
            if fallback or saved_only:
                msg = f"Showing {len(urls)} saved clinics."
            elif not stale:
                msg = f"All {len(fresh)} clinics were checked in the last {config.FRESH_HOURS:g} hours: no re-check needed."
            else:
                msg = (f"{len(fresh)} clinics are up to date; checking {len(stale)} clinic websites..." if fresh
                       else f"Checking {len(stale)} clinic websites...")
            yield common.sse({"type": "stage", "stage": "scan", "message": msg})

            if fallback:
                for c in fallback["clinics"][:limit]:
                    clinic = await scanning.add_location({**c, "last_checked": None, "checked_via": "saved"}, city, user_task)
                    clinics.append(clinic)
                    counts["from_database"] += 1
                    yield common.sse({"type": "clinic_scanned", "clinic": clinic})
            for u in fresh:
                row = rows_by_url[u]
                yield common.sse({"type": "agent_status", "url": u, "message": f"Up to date (checked {ago(row.get('last_checked'))})"})
                clinic = await refresh.locate_and_store(clinic_db.to_clinic(row), city, user_task)
                clinics.append(clinic)
                counts["from_database"] += 1
                yield common.sse({"type": "clinic_scanned", "clinic": clinic})

            if stale:
                queue: asyncio.Queue = asyncio.Queue()

                async def worker(url: str):
                    async def progress(message: str):
                        await queue.put({"type": "agent_status", "url": url, "message": message})

                    try:
                        result = await refresh.check_url(url, city, allow_agent=True, force=refresh_mode == "all", on_progress=progress)
                        clinic = result["clinic"]
                    except Exception as e:
                        clinic = common.failed_clinic(url, f"scan error: {e}")
                    clinic = await refresh.locate_and_store(clinic, city, user_task)
                    await queue.put({"type": "clinic_scanned", "clinic": clinic})

                tasks = [asyncio.create_task(worker(u)) for u in stale]
                done = 0
                while done < len(stale):
                    try:
                        event = await asyncio.wait_for(queue.get(), timeout=15)
                    except asyncio.TimeoutError:
                        yield common.KEEPALIVE
                        continue
                    if event["type"] == "clinic_scanned":
                        done += 1
                        clinics.append(event["clinic"])
                        counts["rechecked"] += 1
                    yield common.sse(event)
                await asyncio.gather(*tasks, return_exceptions=True)
                if set(urls) == set(config.DEFAULT_CLINIC_URLS):
                    cache.save_cache(clinics)  # keep the offline demo backup current

            # ---- Stage 3: Triage Agent ----
            yield common.sse({"type": "stage", "stage": "rank", "message": "Gemini Triage Agent ranking & translating results..."})
            if clinics:
                try:
                    rank_req = models.RankRequest(preferences=req.preferences, clinics=clinics, language=req.language, coverage_type=req.coverage_type)
                    task = asyncio.create_task(asyncio.to_thread(ranking.rank, rank_req))
                    async for ka in common.wait_with_keepalive(task):
                        yield ka
                    ranked = task.result()["ranked_clinics"]
                    yield common.sse({"type": "ranked", "ranked_clinics": ranked})
                except Exception as e:
                    yield common.sse({"type": "error", "stage": "rank", "message": f"Ranking failed: {getattr(e, 'detail', None) or e}. Showing unranked scan results."})
            else:
                yield common.sse({"type": "error", "stage": "rank", "message": "No clinics to rank."})

            # ---- Stage 4: Watchdog auto-enroll ----
            if req.auto_watch_closed and req.user_email:
                yield common.sse({"type": "stage", "stage": "watch", "message": "Watchdog enrolling full clinics for opening alerts..."})
                try:
                    for c in clinics:
                        if c["status"] == "closed" and not common.is_failed(c):  # a failed scan isn't really "closed"
                            watched.append(watchdog.add_watch(c["name"], c["url"], "closed", req.user_email.strip()))
                except Exception as e:
                    yield common.sse({"type": "error", "stage": "watch", "message": f"Watchdog enroll failed: {e}"})
                yield common.sse({"type": "watched", "count": len(watched), "clinics": watched})
            else:
                reason = "no user_email given" if not req.user_email else "auto_watch_closed is off"
                yield common.sse({"type": "stage", "stage": "watch", "message": f"Watchdog skipped ({reason})."})
        except Exception as e:  # never end without a done event
            yield common.sse({"type": "error", "stage": "mission", "message": f"Mission error: {e}"})
        finally:
            for t in [*tasks, user_task]:
                if not t.done():
                    t.cancel()
        ok = [c for c in clinics if not common.is_failed(c)]
        yield common.sse({"type": "done", "summary": {
            "total_scanned": len(clinics),
            "accepting_count": sum(c["status"] == "accepting" for c in ok),
            "waitlist_count": sum(c["status"] == "waitlist" for c in ok),
            "closed_count": sum(c["status"] == "closed" for c in ok),
            "failed_count": len(clinics) - len(ok),
            "watched_count": len(watched),
            "ranked": bool(ranked),
            "top_clinic": ranked[0]["name"] if ranked else None,
            "duration_s": round(time.monotonic() - started_at, 1),
            "from_database": counts["from_database"],
            "rechecked": counts["rechecked"],
        }})

    return StreamingResponse(
        events(), media_type="text/event-stream",
        headers={"Cache-Control": "no-cache", "X-Accel-Buffering": "no"},
    )

"""Clinic database endpoints: list saved clinics instantly, re-check one, add more from a web search."""
import asyncio

from fastapi import APIRouter, HTTPException

from . import config, common, models, clinic_db, refresh, scanning, discovery

router = APIRouter()
_background: set[asyncio.Task] = set()  # keep references so background re-checks aren't garbage-collected


@router.get("/api/clinics")
async def list_clinics(city: str = "London, ON", postal_code: str | None = None, limit: int = 25, include_unchecked: bool = False):
    """Saved clinics for a city, closest first if a postal code is given. Instant: no web requests except the
    postal-code lookup for distances."""
    limit = max(1, min(limit, 200))
    user_loc = await scanning.user_location(postal_code)
    rows = clinic_db.nearby(city, user_loc, limit, include_unchecked=include_unchecked)
    clinics = []
    for row in rows:
        c = clinic_db.to_clinic(row) if row.get("status") else {**common.failed_clinic(row["url"], "scan failed: not checked yet"),
                                                                 "last_checked": None, "checked_via": None}
        if user_loc and c["lat"] is not None and c["lng"] is not None:
            from .geo import haversine_km
            c["distance_km"] = round(haversine_km(user_loc["lat"], user_loc["lng"], c["lat"], c["lng"]), 1)
        clinics.append(c)
    return {"city": city, "clinics": clinics, "stats": clinic_db.stats(config.FRESH_HOURS)}


@router.get("/api/clinics/stats")
def clinic_stats():
    return clinic_db.stats(config.FRESH_HOURS)


@router.post("/api/clinics/refresh")
async def refresh_clinic(req: models.RefreshRequest):
    """Re-check one clinic now (quick page read, browser agent as fallback) and return its updated result."""
    url = req.url.strip()
    if not common.is_http_url(url):
        raise HTTPException(status_code=422, detail="url must be a valid http(s) URL.")
    user_task = asyncio.create_task(scanning.user_location(req.user_postal_code))
    result = await refresh.check_url(url, req.city, allow_agent=True, force=True)
    clinic = await refresh.locate_and_store(result["clinic"], req.city, user_task)
    return {"clinic": clinic, "method": result["method"], "status_changed": result["status_changed"], "error": result["error"]}


@router.post("/api/clinics/seed")
async def seed_clinics(req: models.SeedRequest):
    """Search the web for more clinics in a city, add the new ones, and re-check them in the background."""
    city = req.city.strip() or "London, ON"
    found = await asyncio.to_thread(discovery.discover, models.DiscoverRequest(city=city, max_results=max(1, min(req.max_new, 20))))
    added = [u for u in found["clinic_urls"] if clinic_db.add_url(u, city)]

    async def check_new():
        for u in added:
            result = await refresh.check_url(u, city, allow_agent=config.REFRESH_ALLOW_AGENT)
            if result["method"] in ("page", "agent"):
                await refresh.locate_and_store(result["clinic"], city)

    if added:
        task = asyncio.create_task(check_new())
        _background.add(task)
        task.add_done_callback(_background.discard)
    return {"city": city, "added": added, "found": found["clinic_urls"], "total": clinic_db.count()}

